<section class="content"><div class="page-intro"><p>Monitor available units and keep emergency inventory up to date.</p></div><div class="stock-grid"><?php foreach ($stock as $group => $units): ?><div class="stock-card"><div class="blood-type"><?= h($group) ?></div><div class="stock-count"><strong><?= h((string) $units) ?></strong><span>units available</span></div><div class="stock-bar"><span style="width: <?= min(100, $units * 4) ?>%"></span></div><button class="link-button" data-stock-group="<?= h($group) ?>" data-stock-units="<?= h((string) $units) ?>">Update stock →</button></div><?php endforeach; ?></div></section><div class="modal" id="stock-modal"><div class="modal-box"><button class="modal-close" data-modal-close>×</button><span class="eyebrow">Inventory update</span><h2>Update blood stock</h2><form method="post" class="form-stack"><input type="hidden" name="action" value="stock"><label>Blood group<select name="blood_group" id="stock-group"><?php foreach (array_keys($stock) as $group): ?><option><?= h($group) ?></option><?php endforeach; ?></select></label><label>Available units<input type="number" min="0" name="units" id="stock-units"></label><button class="button primary wide">Save inventory <span>→</span></button></form></div></div>